import json

def transform_dynamic(grid):
    """
    Dynamic quadrant color transformation:
    - Find the unique non-1, non-0 colors in the grid
    - For each quadrant, use the UNIQUE color present in that quadrant
    - If only 1 color exists globally, all 1s become that color
    - Skip quadrants with no colors (rely on global single-color rule if applicable)
    """
    H = len(grid)
    W = len(grid[0])
    h_split = H // 2
    w_split = W // 2

    # Find all colors
    colors_present = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and grid[r][c] != 1:
                colors_present.add(grid[r][c])

    # If only 1 color globally, all 1s become that
    if len(colors_present) == 1:
        target_color = list(colors_present)[0]
    else:
        # Multiple colors: map each quadrant to its unique color
        quadrants = {'TL': [], 'TR': [], 'BL': [], 'BR': []}
        for r in range(H):
            for c in range(W):
                color = grid[r][c]
                if color != 0 and color != 1:
                    if r < h_split and c < w_split:
                        quadrants['TL'].append(color)
                    elif r < h_split and c >= w_split:
                        quadrants['TR'].append(color)
                    elif r >= h_split and c < w_split:
                        quadrants['BL'].append(color)
                    else:
                        quadrants['BR'].append(color)

        # Build mapping - unique color per quadrant, or None
        mapping = {}
        for q, color_list in quadrants.items():
            colors = set(color_list)
            if len(colors) == 1:
                mapping[q] = list(colors)[0]
            else:
                mapping[q] = None

    result = []
    for r in range(H):
        new_row = []
        for c in range(W):
            val = grid[r][c]
            if val == 1:
                if r < h_split and c < w_split:
                    q = 'TL'
                elif r < h_split and c >= w_split:
                    q = 'TR'
                elif r >= h_split and c < w_split:
                    q = 'BL'
                else:
                    q = 'BR'
                if mapping.get(q) is not None:
                    new_row.append(mapping[q])
                elif len(colors_present) == 1:
                    new_row.append(target_color)
                else:
                    new_row.append(1)  # Default to 1 if no mapping
            else:
                new_row.append(val)
        result.append(new_row)
    return result

